@namespace sv_c1325ecfdbba46639b27b9e894f233e1.Components.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrEmpty(channel.Description))
                {
                    <span class="channel-desc">@Truncate(channel.Description, 40)</span>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d31;
    color: #fff;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #1e1f22;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #b5bac1;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    padding: 8px 12px;
    border: none;
    background: none;
    border-radius: 6px;
    color: #949ba4;
    cursor: pointer;
    transition: background 0.1s, color 0.1s;
}

.channel-item:hover {
    background: #35373c;
    color: #dbdee1;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.unread-badge {
    background: #f23f42;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.channel-desc {
    display: block;
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@namespace sv_c1325ecfdbba46639b27b9e894f233e1.Components.Chat
@inject IJSRuntime JS

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        @if (!string.IsNullOrEmpty(ChannelDescription))
        {
            <span class="channel-description">@ChannelDescription</span>
        }
    </div>

    <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == msg.Id);
            <ChatMessageItem Message="msg"
                             IsThreadRoot="@(threadInfo is not null || msg.ReplyToId is null)"
                             ReplyCount="@(threadInfo?.ReplyCount ?? 0)"
                             OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                             OnReact="emoji => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <ChatMessageInput Placeholder="@($"Message #{ChannelName}")" OnSubmit="OnSendMessage" />
</div>

@code {
    private ElementReference messageListRef;

    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public List<Services.ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('[b-chat-msg-list]')?.scrollTop ?? -1");
        if (scrollTop >= 0 && scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.message-area-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #2e3338;
}

.channel-description {
    font-size: 0.85rem;
    color: #72767d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #72767d;
    font-size: 0.85rem;
}

@namespace sv_c1325ecfdbba46639b27b9e894f233e1.Components.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="thread-close" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <span class="quote-author">@RootMessage.Author</span>
            <p class="quote-content">@RootMessage.Content</p>
        </div>
    }

    <div class="thread-messages">
        @foreach (var reply in Replies)
        {
            <ChatMessageItem Message="reply"
                             OnReact="emoji => OnReact.InvokeAsync((reply.Id, emoji))" />
        }
    </div>

    <ChatMessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
</div>

@code {
    [Parameter] public Services.Message? RootMessage { get; set; }
    [Parameter] public List<Services.Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #f9f9f9;
    border-left: 1px solid #e0e0e0;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #2e3338;
}

.thread-close {
    padding: 4px 8px;
    border: none;
    background: none;
    font-size: 1.1rem;
    color: #72767d;
    cursor: pointer;
    border-radius: 4px;
}

.thread-close:hover {
    background: #e0e0e0;
    color: #2e3338;
}

.thread-root-quote {
    margin: 12px 16px;
    padding: 8px 12px;
    background: #eef0f4;
    border-left: 3px solid #5865f2;
    border-radius: 0 4px 4px 0;
    flex-shrink: 0;
}

.quote-author {
    font-weight: 700;
    font-size: 0.85rem;
