toolArgs.file_text:
@page "/chat"
@layout sv_c1325ecfdbba46639b27b9e894f233e1.Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_c1325ecfdbba46639b27b9e894f233e1.Components.Chat
@using sv_c1325ecfdbba46639b27b9e894f233e1.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChatChannelSidebar Channels="channels"
                            ActiveChannelId="activeChannelId"
                            OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "with-thread" : "")">
        @if (activeChannel is not null)
        {
            <ChatMessageArea ChannelName="@activeChannel.Name"
                             ChannelDescription="@activeChannel.Description"
                             Messages="messages"
                             ThreadSummaries="threadSummaries"
                             IsLoadingMore="isLoadingMore"
                             OnOpenThread="OpenThread"
                             OnReact="HandleReaction"
                             OnSendMessage="SendMessage"
                             OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ChatThreadPanel RootMessage="threadRootMessage"
                             Replies="threadReplies"
                             OnClose="CloseThread"
                             OnSendReply="SendThreadReply"
                             OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private Channel? activeChannel;
    private int activeChannelId;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private bool isLoadingMore;
    private const int PageSize = 50;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        threadSummaries = BuildThreadSummaries(messages);
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (activeChannel is null || isLoadingMore) return;
        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            threadSummaries = BuildThreadSummaries(messages);
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (activeChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary in main view
        threadSummaries = BuildThreadSummaries(messages, threadRootMessage.Id, threadReplies.Count);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        UpdateReactionLocally(messages, args.MessageId, args.Emoji);
        UpdateReactionLocally(threadReplies, args.MessageId, args.Emoji);
    }

    private static void UpdateReactionLocally(List<Message> msgList, int messageId, string emoji)
    {
        var idx = msgList.FindIndex(m => m.Id == messageId);
        if (idx < 0) return;

        var msg = msgList[idx];
        var reactions = msg.Reactions.ToList();
        var existing = reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            reactions.Remove(existing);
            reactions.Add(existing with { Users = [..existing.Users, "You"] });
        }
        else
        {
            reactions.Add(new Reaction(emoji, ["You"]));
        }
        msgList[idx] = msg with { Reactions = reactions };
    }

    private List<ThreadSummary> BuildThreadSummaries(List<Message> msgs, int? updatedRootId = null, int? updatedCount = null)
    {
        var rootIds = msgs
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        if (updatedRootId is not null)
        {
            var existingIdx = rootIds.FindIndex(t => t.RootMessageId == updatedRootId);
            var summary = new ThreadSummary(updatedRootId.Value, updatedCount ?? 1, DateTime.UtcNow);
            if (existingIdx >= 0)
                rootIds[existingIdx] = summary;
            else
                rootIds.Add(summary);
        }

        return rootIds;
    }
}

